namespace {
void check(hipError_t e){if(e!=hipSuccess)throw std::runtime_error(hipGetErrorString(e));}
std::vector<std::vector<std::string>> table(const std::filesystem::path&p,size_t n){std::ifstream f(p);if(!f)throw std::runtime_error("table open");std::vector<std::vector<std::string>>out;std::string line;while(std::getline(f,line)){std::vector<std::string>r;std::stringstream s(line);std::string c;while(std::getline(s,c,'\t'))r.push_back(c);if(r.size()!=n)throw std::runtime_error("table columns");out.push_back(r);}return out;}
std::string escape(const std::string&s){std::string out;for(char c:s){if(c=='\\'||c=='"')out+='\\';out+=c;}return out;}
template<class T>std::vector<T> read(const std::filesystem::path&p,size_t count){if(std::filesystem::file_size(p)!=count*sizeof(T))throw std::runtime_error("input exact bytes");artifact::FixtureView view{p,0,count*sizeof(T)};auto bytes=view.read_exact(0,count*sizeof(T));std::vector<T>v(count);if(!v.empty())std::memcpy(v.data(),bytes.data(),bytes.size());return v;}
void output(const std::filesystem::path&p,const deepseek41::KvTrace&t){if(!std::filesystem::create_directory(p))throw std::runtime_error("preserve existing output");std::ofstream index(p/"stages.tsv");for(const auto&[name,s]:t.stages){std::ofstream f(p/(name+".bin"),std::ios::binary);f.write((const char*)s.bytes.data(),s.bytes.size());if(!f)throw std::runtime_error("output write");index<<name<<'\t'<<s.dtype<<'\t'<<s.rows<<'\t'<<s.columns<<'\t'<<s.bytes.size()<<'\n';}}
unsigned state_test(){using deepseek41::KvSequence;unsigned checks=0;auto require=[&](bool b){if(!b)throw std::runtime_error("state assertion");++checks;};auto reject=[&](auto fn){try{fn();}catch(const std::exception&){++checks;return;}throw std::runtime_error("state expected rejection");};
 for(uint64_t length:{1,2,3,127,128,129}){KvSequence a,b;a.reset(1);b.reset(1);auto view=a.prefill(length,1);require(view.kind==deepseek41::KvWindowView::Kind::PrefillChunk&&view.rows==length);for(uint64_t p=0;p<length;++p){if(!p)b.prefill(1,1);else{auto ring=b.append(p,1);require(ring.kind==deepseek41::KvWindowView::Kind::DecodeRing&&ring.rows==128);}}
  for(int writer:{2,8,14,20}){require(a.rows(writer)==b.rows(writer));require(a.pending(writer)==b.pending(writer));a.publish(writer,a.rows(writer),1);for(int layer=writer;layer<(writer==2?8:writer==8?14:writer==14?20:40);++layer)require(a.read(layer,1)==a.rows(writer));}
  reject([&]{a.publish(1,0,1);});reject([&]{a.publish(2,a.rows(2)+1,1);});reject([&]{a.read(2,2);});reject([&]{a.append(length+1,1);});a.reuse_exact_prefix(2);require(a.position()==length);reject([&]{a.read(20,2);});reject([&]{a.append(length,1);});a.append(length,2);a.cancel(2);reject([&]{a.publish(20,length+1,2);});reject([&]{a.append(length+1,2);});reject([&]{a.reuse_exact_prefix(3);});a.reset(3);require(a.position()==0&&a.rows(2)==0&&!a.pending(2));}
 KvSequence s;reject([&]{s.reset(0);});s.reset(1);s.prefill(129,1);s.publish(2,64,1);reject([&]{s.read(8,1);});s.publish(8,64,1);require(s.read(8,1)==64);reject([&]{s.read(0,1);});reject([&]{s.prefill(1,1);});return checks;}
void alloc_probe(){
 int ordinal=-1;hipCtx_t ctx=nullptr;auto ds=hipGetDevice(&ordinal),cs=hipCtxGetCurrent(&ctx);size_t free=0,total=0;auto ms=hipMemGetInfo(&free,&total);std::cerr<<"alloc-before device_status="<<int(ds)<<" device="<<ordinal<<" ctx_status="<<int(cs)<<" ctx="<<ctx<<" mem_status="<<int(ms)<<" free="<<free<<" total="<<total<<std::endl;
 void*p=nullptr,*q=nullptr;std::cerr<<"malloc1 n=163840 &p="<<&p<<" p="<<p<<std::endl;auto a=hipMalloc(&p,163840);std::cerr<<"malloc1 status="<<int(a)<<" p="<<p<<std::endl;check(a);std::cerr<<"malloc2 n=163840 &q="<<&q<<" q="<<q<<std::endl;auto b=hipMalloc(&q,163840);std::cerr<<"malloc2 status="<<int(b)<<" q="<<q<<std::endl;check(b);check(hipFree(q));check(hipFree(p));std::cerr<<"alloc-cleanup-ready"<<std::endl;
}
}
int main(int argc,char**argv){try{
 if(argc==2&&std::string(argv[1])=="--identity"){std::cout<<"{\"source_id\":\""<<T14_SOURCE_ID<<"\"}";return 0;}
 if(argc==2&&std::string(argv[1])=="--state"){std::cout<<"{\"state_assertions\":"<<state_test()<<"}";return 0;}
 if(argc==2&&std::string(argv[1])=="--alloc-only"){int count=0,device=-1;check(hipGetDeviceCount(&count));for(int i=0;i<count;++i){char pci[64]={};check(hipDeviceGetPCIBusId(pci,sizeof(pci),i));if(std::string(pci)=="0000:07:00.0")device=i;}if(device<0)throw std::runtime_error("probe exact PCI");check(hipSetDevice(device));alloc_probe();return 0;}
 if(argc!=10||std::string(argv[1])!="--run")throw std::runtime_error("--run PCI weights sources prefixes jobs controls input8 out");
 auto mark=[](const char*s){if(std::getenv("T14_DIAGNOSTIC"))std::cerr<<s<<std::endl;};mark("artifact-begin");deepseek41::SourceSet sources;for(const auto&r:table(argv[4],5)){deepseek41::SourceFile f;f.shard_index=std::stoul(r[0]);f.original_size=std::stoull(r[1]);f.lfs_sha256=r[2];f.revision=r[3];f.original_path=r[4];if(sources.root.empty())sources.root=f.original_path.parent_path();sources.files.push_back(f);}std::vector<artifact::PrefixIndex>prefixes;std::string first;for(const auto&r:table(argv[5],2)){if(first.empty())first=r[1];prefixes.push_back(artifact::inspect_prefix(r[1],std::stoull(r[0])));}deepseek41::Artifact index(artifact::merge_prefixes(prefixes),deepseek41::inspect_metadata(first),sources);deepseek41::KvWeights weights;
 for(const auto&r:table(argv[3],4)){auto s=index.source_tensor(r[0]);if(s.span.absolute_offset!=std::stoull(r[1])||s.span.bytes!=std::stoull(r[2]))throw std::runtime_error("KV original span");artifact::FixtureView v{r[3],s.span.absolute_offset,s.span.bytes};if(!weights.emplace(r[0],deepseek41::KvWeight{s,v.read_exact(s.span.absolute_offset,s.span.bytes)}).second)throw std::runtime_error("duplicate weight");}if(weights.size()!=13)throw std::runtime_error("KV weight coverage");
 mark("artifact-weights-ready");int count=0,selected=-1;mark("device-count");check(hipGetDeviceCount(&count));mark("device-count-ready");for(int i=0;i<count;++i){char pci[64]={};check(hipDeviceGetPCIBusId(pci,sizeof(pci),i));if(std::string(pci)==argv[2])selected=i;}if(selected<0)throw std::runtime_error("exact PCI absent");mark("device-select");check(hipSetDevice(selected));mark("device-selected");if(std::getenv("T14_ALLOC_PROBE_AFTER_ARTIFACT")){alloc_probe();return 0;}hipDeviceProp_t prop{};check(hipGetDeviceProperties(&prop,selected));size_t before_free=0,before_total=0,after_free=0,after_total=0;auto before=hipMemGetInfo(&before_free,&before_total);
 std::filesystem::path out(argv[9]);if(!std::filesystem::create_directory(out))throw std::runtime_error("preserve output root");std::ostringstream jobs;jobs<<"[";bool firstjob=true;auto report=[&](const std::string&name,const deepseek41::KvTrace&t){if(!firstjob)jobs<<",";firstjob=false;jobs<<"{\"name\":\""<<name<<"\",\"stages\":"<<t.stages.size()<<",\"primitive_peak\":"<<t.primitive_peak<<",\"scratch_peak\":"<<t.scratch_peak<<",\"cleanup_unknown\":"<<(t.cleanup_unknown?"true":"false")<<"}";};
 measurement::Identity id;id.fixture_sha256=T14_SOURCE_ID;id.asset_sha256=sources.files[8].lfs_sha256;id.bundle_sha256=T14_SOURCE_ID;id.request_id="t14";id.epoch=1;id.phase=measurement::Phase::Decode;auto input8=read<float>(argv[8],8*5120);mark("projection8-begin");auto projection8=deepseek41::kv_project(input8,8,weights,id,argv[2]);
 mark("projection8-ready");for(const auto&r:table(argv[6],6)){const auto&name=r[0];unsigned batch=std::stoul(r[2]),phase=std::stoul(r[3]);uint64_t length=std::stoull(r[4]);deepseek41::KvTrace t;
  if(r[1]=="projection"){t=deepseek41::kv_project(read<float>(r[5],batch*5120),batch,weights,id,argv[2]);}
  else if(r[1]=="temporal"){t=deepseek41::kv_temporal(projection8,length,phase,weights);}
  else if(r[1]=="append"){t=deepseek41::kv_append_replay(projection8,length,phase,weights);}
  else if(r[1]=="temporal_batch"){for(unsigned context=0;context<batch;++context){auto part=deepseek41::kv_temporal(projection8,length,(phase+context)%8,weights);for(auto&[n,s]:part.stages)t.stages.emplace("c"+std::to_string(context)+"__"+n,std::move(s));t.scratch_peak=std::max(t.scratch_peak,part.scratch_peak);if(part.cleanup_unknown)t.cleanup_unknown=true;}}
  else throw std::runtime_error("KV job kind");output(out/name,t);report(name,t);
 }
 for(const auto&r:table(argv[7],2)){deepseek41::KvFloats input;std::filesystem::path folder(r[1]);std::vector<int64_t>positions;if(r[0].rfind("pool-",0)==0){input["kv"]=read<float>(folder/"kv.bin",1024);input["score"]=read<float>(folder/"score.bin",1024);}else{unsigned rows=r[0].rfind("rope",0)==0?5:1;input["input"]=read<float>(folder/"input.bin",rows*512);if(rows==5)positions=read<int64_t>(folder/"positions.bin",5);}auto t=deepseek41::kv_control(r[0],input,positions);output(out/("controlled-"+r[0]),t);report("controlled-"+r[0],t);}
 jobs<<"]";check(hipDeviceSynchronize());auto after=hipMemGetInfo(&after_free,&after_total);HMODULE modules[1024];DWORD needed=0;if(!EnumProcessModules(GetCurrentProcess(),modules,sizeof(modules),&needed)||needed>sizeof(modules))throw std::runtime_error("loaded modules");std::cout<<"{\"source_id\":\""<<T14_SOURCE_ID<<"\",\"pci\":\""<<argv[2]<<"\",\"arch\":\""<<prop.gcnArchName<<"\",\"state_assertions\":"<<state_test()<<",\"jobs\":"<<jobs.str()<<",\"source_qualified\":false,\"loaded_modules\":[";for(unsigned i=0;i<needed/sizeof(HMODULE);++i){char p[32768];if(!GetModuleFileNameA(modules[i],p,sizeof(p)))throw std::runtime_error("module path");if(i)std::cout<<",";std::cout<<"\""<<escape(p)<<"\"";}std::cout<<"],\"before_status\":"<<int(before)<<",\"before_free\":";if(before==hipSuccess)std::cout<<before_free;else std::cout<<"null";std::cout<<",\"before_total\":";if(before==hipSuccess)std::cout<<before_total;else std::cout<<"null";std::cout<<",\"after_status\":"<<int(after)<<",\"after_free\":";if(after==hipSuccess)std::cout<<after_free;else std::cout<<"null";std::cout<<",\"after_total\":";if(after==hipSuccess)std::cout<<after_total;else std::cout<<"null";std::cout<<"}";return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 2;}}
